/* ===================== DATA ===================== */
/* ======================================================================
   NEON + VERCEL SETUP — REQUIRED ONE-TIME STEP
   1. Deploy this project to Vercel (vercel.com) — it already contains
      /api/data.js, /api/upload.js and /api/delete-blob.js as serverless
      functions, so no separate backend is needed.
   2. Create a Neon Postgres database (neon.tech) and run schema.sql
      against it (Neon SQL editor, or `psql "$DATABASE_URL" -f schema.sql`).
   3. In Vercel → Project → Settings → Environment Variables, add:
        DATABASE_URL          = your Neon connection string
        BLOB_READ_WRITE_TOKEN = created automatically when you add the
                                 "Blob" storage integration in Vercel →
                                 Storage → Create Database → Blob
   4. Redeploy. The page loads data from /api/data and polls it every
      few seconds so changes show up on other open tabs/devices —
      Postgres doesn't push changes like Firestore did, so this is a
      lightweight substitute for that "live sync" behaviour.
   ====================================================================== */

/* Turns an upload/save error into a plain-English reason. */
function explainStorageError(err){
  const msg = (err && err.message) || 'Unknown error';
  if (/network|fetch/i.test(msg)) return 'Network error talking to the server — check your connection and try again.';
  if (/token|unauthorized|forbidden/i.test(msg)) return 'The server rejected this upload. Check BLOB_READ_WRITE_TOKEN is set in Vercel.';
  return msg;
}

