function getInitialCachedData(){
  try{
    const cached = localStorage.getItem('gurukul_cached_data');
    if(cached){
      return mergeWithDefaults(JSON.parse(cached));
    }
  }catch(e){}
  return defaultData();
}

let data = getInitialCachedData();
let isAdmin = false;
let suppressNextPoll = false;
let dataReadyResolve;
const dataReady = new Promise(res => { dataReadyResolve = res; });
let lastKnownUpdatedAt = null;

function mergeWithDefaults(parsed){
  const def = defaultData();
  return {
    profile: Object.assign({}, def.profile, (parsed && parsed.profile) || {}),
    groups: (parsed && parsed.groups) || def.groups,
    vacancies: (parsed && parsed.vacancies) || def.vacancies,
    applications: (parsed && parsed.applications) || def.applications,
    children: (parsed && parsed.children) || def.children,
    gallery: (parsed && parsed.gallery) || def.gallery,
    extraInfo: (parsed && parsed.extraInfo) || def.extraInfo
  };
}

async function loadData(){
  try{
    const resp = await fetch('/api/data');
    if(!resp.ok) {
      console.warn('API /api/data returned status ' + resp.status + '; using cached/default data.');
      if(!data) data = getInitialCachedData();
      return;
    }
    const contentType = resp.headers.get('content-type') || '';
    if (!contentType.includes('application/json')) {
      console.warn('API /api/data returned non-JSON content; using cached/default data.');
      if(!data) data = getInitialCachedData();
      return;
    }
    const json = await resp.json();
    if(json && json.data){
      data = mergeWithDefaults(json.data);
      lastKnownUpdatedAt = json.updatedAt;
      try{ localStorage.setItem('gurukul_cached_data', JSON.stringify(data)); }catch(e){}
    } else {
      // First time ever running — seed the row with the starter data.
      data = defaultData();
      await saveData();
    }
  }catch(e){
    console.warn('Notice: Using cached/default data state.', e && e.message ? e.message : e);
    if(!data) data = getInitialCachedData();
  }
}

let saveDebounceTimer = null;
async function saveData(){
  try{ localStorage.setItem('gurukul_cached_data', JSON.stringify(data)); }catch(e){}
  suppressNextPoll = true;
  clearTimeout(saveDebounceTimer);
  return new Promise((resolve) => {
    saveDebounceTimer = setTimeout(async () => {
      try{
        const resp = await fetch('/api/data', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data)
        });
        if(resp.ok){
          const contentType = resp.headers.get('content-type') || '';
          if(contentType.includes('application/json')){
            const json = await resp.json();
            if(json && json.updatedAt){
              lastKnownUpdatedAt = json.updatedAt;
            }
          }
        }
      }catch(e){
        console.warn('Background save note:', e);
      }
      resolve();
    }, 20);
  });
}

function isAppFullyVerified(a){
  if(!a) return false;
  if(a.verified === true) return true;
  const needsCv = !!a.cvFileUrl;
  const needsPayment = !!a.paymentFileUrl;
  if(!needsCv && !needsPayment) return false;
  if(needsCv && !a.cvVerified) return false;
  if(needsPayment && !a.paymentVerified) return false;
  return true;
}

function isVacancyVerified(v){
  if(!v) return false;
  if(v.status === 'verified' || v.status === 'filled' || v.verified === true) return true;
  const apps = (data.applications || []).filter(a => a.vacancyId === v.id);
  return apps.some(a => a.verified === true || isAppFullyVerified(a));
}

function getVacancyApplicantCount(vacId){
  if(!vacId) return 0;
  return (data.applications || []).filter(a => a.vacancyId === vacId).length;
}

// Near-live sync: since Postgres has no built-in push like Firestore,
// every open tab quietly polls for changes made elsewhere (by the admin,
// or by another visitor) and re-renders when something changed.
const POLL_INTERVAL_MS = 5000;
async function pollForChanges(){
  if(document.hidden) return; // Save bandwidth and CPU when tab is in background
  if(suppressNextPoll){ suppressNextPoll = false; return; }
  try{
    const resp = await fetch('/api/data');
    if(!resp.ok) return;
    const contentType = resp.headers.get('content-type') || '';
    if(!contentType.includes('application/json')) return;
    const json = await resp.json();
    if(!json || !json.data) return;
    if(json.updatedAt && json.updatedAt === lastKnownUpdatedAt) return; // nothing changed
    lastKnownUpdatedAt = json.updatedAt;
    data = mergeWithDefaults(json.data);
    renderAll();
    if(isAdmin){
      renderAdminGroups(); renderAdminVacancies(); renderAdminApplications(); renderAdminChildren(); renderAdminGallery(); renderAdminInfo();
    }
  }catch(e){
    // Silent — a missed poll isn't worth alarming the visitor about.
    console.warn('Poll for changes note:', e && e.message ? e.message : e);
  }
}
setInterval(pollForChanges, POLL_INTERVAL_MS);

function uid(prefix){ return prefix + Date.now().toString(36) + Math.floor(Math.random()*1000); }

/* Deleting an image/blob calls the /api/delete-blob route which handles Cloudinary & Vercel Blob */
function deleteBlob(url){
  if(!url) return;
  fetch('/api/delete-blob', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ url })
  }).catch(()=>{});
}
window.deleteMedia = deleteBlob;

/* Uploads an image/file to Cloudinary via server-side /api/upload with fallback */
async function uploadToCloudinaryOrStorage(fileOrDataUrl, folder = 'gurukul', filename = '') {
  try {
    let payload = fileOrDataUrl;
    if (fileOrDataUrl instanceof File || fileOrDataUrl instanceof Blob) {
      if (fileOrDataUrl.type && fileOrDataUrl.type.startsWith('image/')) {
        payload = await new Promise((resolve) => compressImageFile(fileOrDataUrl, resolve));
      } else {
        payload = await new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result);
          reader.onerror = reject;
          reader.readAsDataURL(fileOrDataUrl);
        });
      }
    }

    const res = await fetch('/api/upload', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        file: payload,
        folder: folder,
        filename: filename || ('upload_' + Date.now())
      })
    });

    if (!res.ok) {
      const errJson = await res.json().catch(() => ({}));
      console.warn('Server upload response not ok:', res.status, errJson);
      throw new Error(errJson.error || `Upload failed with HTTP ${res.status}`);
    }

    const result = await res.json();
    return result.url || payload;
  } catch (err) {
    console.warn('Cloudinary/API upload fallback:', err);
    if (typeof fileOrDataUrl === 'string') return fileOrDataUrl;
    if (fileOrDataUrl.type && fileOrDataUrl.type.startsWith('image/')) {
      return await new Promise((resolve) => compressImageFile(fileOrDataUrl, resolve));
    }
    return await new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => resolve('');
      reader.readAsDataURL(fileOrDataUrl);
    });
  }
}
window.uploadToCloudinaryOrStorage = uploadToCloudinaryOrStorage;

/* Check active storage and database backend status */
async function getBackendIntegrationStatus() {
  try {
    const res = await fetch('/api/upload');
    if (res.ok) {
      return await res.json();
    }
  } catch (e) {}
  return { cloudinary: false, vercelBlob: false, neonDatabase: false, provider: 'local' };
}
window.getBackendIntegrationStatus = getBackendIntegrationStatus;

/* Resizes + compresses an image file client-side and returns a JPEG data URL,
   so gallery/logo photos can be stored inline in the JSONB data row in Neon
   or sent efficiently to Cloudinary. */
function compressImageFile(file, callback){

  const reader = new FileReader();
  reader.onload = function(ev){
    const img = new Image();
    img.onload = function(){
      const maxW = 900;
      const scale = Math.min(1, maxW / img.width);
      const canvas = document.createElement('canvas');
      canvas.width = Math.round(img.width * scale);
      canvas.height = Math.round(img.height * scale);
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      callback(canvas.toDataURL('image/jpeg', 0.7));
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
}

/* Helper to get formatted admin WhatsApp number */
function getAdminWhatsAppNumber(){
  const phone = (data && data.profile && data.profile.phone) || '+977-9801775074';
  const clean = phone.replace(/[^0-9]/g, '');
  return clean.length >= 8 ? clean : '9779801775074';
}

/* Helper to build formatted WhatsApp CV Statement & application details */
function buildWhatsAppCvStatement(app){
  if(!app) return '';
  const subDate = app.submittedAt ? new Date(app.submittedAt).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }) : new Date().toLocaleString();
  const cvSummary = app.cvText ? app.cvText : (app.cvFileName ? `[Attached CV File: ${app.cvFileName}]` : 'Not specified');
  const cvLinkStr = app.cvLink ? app.cvLink : (app.cvFileUrl && !app.cvFileUrl.startsWith('data:') ? app.cvFileUrl : '');
  const payStr = app.paymentFileName ? `Screenshot: ${app.paymentFileName}` : (app.paymentFileUrl ? 'Payment screenshot attached' : 'Pending / Will pay before demo classes');

  const lines = [
    `🎓 *GURUKUL HOME TUITIONS - TEACHER VACANCY APPLICATION*`,
    ``,
    `📌 *Position Applied:* ${app.vacancyTitle || 'Tutor Vacancy'}`,
    `👤 *Teacher Name:* ${app.name || 'N/A'}`,
    `📞 *Phone Number:* ${app.phone || 'N/A'}`,
    ``,
    `📄 *CV / Resume Statement:*`,
    `${cvSummary}`,
    ``,
    cvLinkStr ? `🔗 *CV / Portfolio Link:* ${cvLinkStr}` : null,
    `🧾 *35% Commission Payment:* ${payStr}`,
    `✍️ *Teacher Policy Agreed:* Yes (Signed as: ${app.signature || app.name || 'Applicant'})`,
    `📅 *Submitted Date:* ${subDate}`,
    ``,
    `----------------------------------------`,
    `Sent from Gurukul Home Tuitions (gurukultuition.vercel.app)`
  ].filter(line => line !== null);

  return lines.join('\n');
}

